+/** Picks a supported language from an Accept-Language header, falling back to `fallback`. */
+export function pickLanguage(header, fallback = "en") {
+  const baseFallback = LANGUAGES.includes(fallback) ? fallback : LANGUAGES[0];
+  if (typeof header !== "string" || !header.trim()) return baseFallback;
+
+  const candidates = [];
+  const parts = header.split(",");
+  for (let i = 0; i < parts.length; i++) {
+    const raw = parts[i].trim();
+    if (!raw) continue;
+    const [tagPart, ...params] = raw.split(";");
+    const tag = tagPart.trim().toLowerCase();
+    if (!tag) continue;
+
+    let q = 1;
+    let valid = true;
+    for (const param of params) {
+      const m = param.trim().match(/^q\s*=\s*(.+)$/i);
+      if (!m) continue;
+      const parsed = Number(m[1]);
+      if (Number.isNaN(parsed) || parsed < 0 || parsed > 1) {
+        valid = false;
+        break;
+      }
+      q = parsed;
+    }
+    if (!valid || q === 0) continue;
+
+    const primary = tag.split("-")[0];
+    if (LANGUAGES.includes(primary)) {
+      candidates.push({ lang: primary, q, index: i });
+    }
+  }
+
+  if (!candidates.length) return baseFallback;
+  candidates.sort((a, b) => b.q - a.q || a.index - b.index);
+  return candidates[0].lang;
+}
